"use client";

import { createContext, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { AlertCircle, ArrowLeft, BarChart3, Bell, BookOpen, CalendarCheck, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, Clock3, CreditCard, Download, Eye, FileDown, GraduationCap, LayoutDashboard, Layers3, LockKeyhole, LogOut, Menu, MoreHorizontal, Pencil, Plus, Printer, ReceiptText, Search, Settings2, ShieldCheck, Sparkles, Trash2, TrendingDown, TrendingUp, UserPlus, UsersRound, Wallet, X } from "lucide-react";
import { AttendanceChart, ExpenseChart, FinanceChart, GroupChart, PaymentDonut, ProfitChart } from "./charts";
import { ModalRenderer, type ModalState } from "./modals";
import { makeDemoData } from "@/lib/demo";
import type { Dataset, Group, Student } from "@/lib/types";
import { currentMonth, days, formatDate, formatMoney, paidFor, studentBalance, today } from "@/lib/types";

type View = "dashboard" | "students" | "groups" | "group" | "attendance" | "payments" | "expenses" | "homework" | "analytics" | "settings";
type Ctx = { data: Dataset; month: string; setMonth: (s: string) => void; search: string; setSearch: (s: string) => void; setView: (v: View) => void; groupId: number; setGroupId: (n: number) => void; open: (m: ModalState, protect?: boolean) => void; remove: (action: string, id: number, message: string) => void; downloadBackup: () => void; restoreBackup: (file: File) => Promise<void>; exportCSV: () => void; printReport: () => void; authenticated: boolean; busy: boolean; logout: () => void };
const AppContext = createContext<Ctx | null>(null);
function useApp() { const context = useContext(AppContext); if (!context) throw new Error("Missing dashboard context"); return context; }
const nav: { view: View; label: string; icon: typeof LayoutDashboard }[] = [
  { view: "dashboard", label: "لوحة التحكم", icon: LayoutDashboard }, { view: "students", label: "الطلاب", icon: UsersRound }, { view: "groups", label: "المجموعات", icon: Layers3 }, { view: "attendance", label: "الحضور والغياب", icon: CalendarCheck }, { view: "payments", label: "المدفوعات", icon: Wallet }, { view: "expenses", label: "المصروفات", icon: ReceiptText }, { view: "homework", label: "الواجب والحفظ", icon: BookOpen }, { view: "analytics", label: "التقارير والتحليلات", icon: BarChart3 },
];
const pageNames: Record<View,string> = { dashboard: "لوحة التحكم", students: "إدارة الطلاب", groups: "إدارة المجموعات", group: "تفاصيل المجموعة", attendance: "الحضور والغياب", payments: "المدفوعات والاشتراكات", expenses: "المصروفات", homework: "الواجب والحفظ", analytics: "التقارير والتحليلات", settings: "الإعدادات" };
const money = (n: number) => `${formatMoney(n)} ج.م`;
const timeLabel = (t: string) => { const [hour, minute] = t.split(":").map(Number); return `${hour % 12 || 12}:${String(minute).padStart(2,"0")} ${hour >= 12 ? "م" : "ص"}`; };
const monthLabel = (month: string) => { const d = new Date(`${month}-01T12:00:00`); return Number.isNaN(d.getTime()) ? month : new Intl.DateTimeFormat("ar-EG", { month: "long", year: "numeric" }).format(d); };
const shortName = (name: string) => name.trim().charAt(0);
const groupColor = (color: string) => `tone-${color || "blue"}`;
function statusInfo(status: string, due = 1) { if (!due) return { label: "بدون اشتراك", className: "status-neutral" }; if (status === "paid") return { label: "مدفوع", className: "status-paid" }; if (status === "partial") return { label: "مدفوع جزئياً", className: "status-partial" }; return { label: "غير مدفوع", className: "status-unpaid" }; }
function Status({ status, due = 1 }: { status: string; due?: number }) { const info = statusInfo(status,due); return <span className={`status ${info.className}`}><i/>{info.label}</span>; }
function Avatar({ name, index = 0 }: { name: string; index?: number }) { return <span className={`avatar avatar-${index % 5}`}>{shortName(name)}</span>; }
function Empty({ title, text, icon: Icon = Search, action }: { title: string; text: string; icon?: typeof Search; action?: ReactNode }) { return <div className="empty-state"><span><Icon size={24}/></span><strong>{title}</strong><p>{text}</p>{action}</div>; }
function PageHeading({ eyebrow, title, description, children }: { eyebrow?: string; title: string; description: string; children?: ReactNode }) { return <div className="page-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>; }
function SectionHeading({ title, subtitle, children }: { title: string; subtitle?: string; children?: ReactNode }) { return <div className="section-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><div className="section-actions">{children}</div></div>; }
function MonthInput({ value, onChange }: { value: string; onChange: (v: string) => void }) { return <label className="month-control"><CalendarDays size={15}/><input aria-label="اختيار الشهر" type="month" value={value} onChange={e => e.target.value && onChange(e.target.value)}/></label>; }
function downloadFile(filename: string, content: string, type: string) { const url = URL.createObjectURL(new Blob([content], { type })); const a = document.createElement("a"); a.href = url; a.download = filename; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
function escapeHTML(s: unknown) { return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c] || c)); }

export default function TeacherDashboard({ initialData, initialAuthenticated, demoCredentials }: { initialData: Dataset; initialAuthenticated: boolean; demoCredentials: boolean }) {
  const [data, setData] = useState(initialData); const [authenticated, setAuthenticated] = useState(initialAuthenticated); const [showDemoCredentials, setShowDemoCredentials] = useState(demoCredentials);
  const [view, setViewState] = useState<View>("dashboard"); const [groupId, setGroupId] = useState(0); const [month, setMonth] = useState(currentMonth()); const [search, setSearch] = useState("");
  const [modal, setModal] = useState<ModalState | null>(null); const [busy, setBusy] = useState(false); const [sidebar, setSidebar] = useState(false); const [bell, setBell] = useState(false); const [toast, setToast] = useState<{ text: string; error?: boolean } | null>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  useEffect(() => { const shortcut = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); if (window.innerWidth <= 650) { setViewState("students"); window.setTimeout(() => document.querySelector<HTMLInputElement>('.input-search input')?.focus(), 50); } else searchRef.current?.focus(); } }; window.addEventListener("keydown", shortcut); return () => window.removeEventListener("keydown", shortcut); }, []);
  const notify = (text: string, error = false) => { setToast({ text, error }); window.setTimeout(() => setToast(null), 4000); };
  const setView = (next: View) => { setViewState(next); setSidebar(false); setBell(false); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const open = (next: ModalState, protect = false) => { if (protect && !authenticated) { setModal({ type: "login" }); notify("سجّل الدخول أولاً لحفظ التغييرات"); return; } setModal(next); };
  const refresh = async () => { const response = await fetch("/api/data", { cache: "no-store" }); if (!response.ok) throw new Error("تعذر تحديث البيانات"); setData(await response.json()); };
  const onAction = async (action: string, payload: Record<string, unknown>) => {
    if (!authenticated) { setModal({ type: "login" }); return false; }
    setBusy(true); const previous = data;
    const collection: Record<string, keyof Dataset> = { deleteStudent: "students", deleteGroup: "groups", deleteExpense: "expenses", deletePayment: "payments", deleteAssignment: "assignments" };
    if (collection[action]) { const key = collection[action]; setData(old => ({ ...old, [key]: old[key].filter(item => item.id !== Number(payload.id)) })); }
    try { const response = await fetch("/api/actions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...payload }) }); const result = await response.json(); if (response.status === 401) { setAuthenticated(false); setData(makeDemoData()); setModal({ type: "login" }); notify("انتهت الجلسة، سجّل الدخول مجدداً", true); return false; } if (!response.ok) throw new Error(result.error || "تعذر حفظ البيانات"); await refresh(); notify(action.startsWith("delete") ? "تم حذف السجل بنجاح" : "تم حفظ البيانات بنجاح"); return true; }
    catch (error) { setData(previous); notify(error instanceof Error ? error.message : "حدث خطأ غير متوقع", true); return false; } finally { setBusy(false); }
  };
  const remove = (action: string, id: number, message: string) => { if (!authenticated) { open({ type: "login" }); return; } if (window.confirm(message)) void onAction(action, { id }); };
  const onLogin = async (username: string, password: string) => { setBusy(true); try { const response = await fetch("/api/auth", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "login", username, password }) }); const result = await response.json(); if (!response.ok) return result.error || "تعذر تسجيل الدخول"; await refresh(); setAuthenticated(true); setModal(null); notify("أهلاً بعودتك، مستر ميخائيل"); return null; } catch { return "تعذر الاتصال بالخادم"; } finally { setBusy(false); } };
  const logout = async () => { try { await fetch("/api/auth", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "logout" }) }); } catch { /* Reset the local view even if the connection fails. */ } setAuthenticated(false); setData(makeDemoData()); setModal(null); setView("dashboard"); notify("تم تسجيل الخروج"); };
  const onPassword = async (oldPassword: string, newPassword: string) => { setBusy(true); try { const response = await fetch("/api/auth", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "password", oldPassword, newPassword }) }); const result = await response.json(); if (!response.ok) return result.error; setShowDemoCredentials(false); setAuthenticated(false); setData(makeDemoData()); setModal(null); setView("dashboard"); notify("تم تغيير كلمة المرور. سجّل الدخول مجدداً."); return null; } catch { return "تعذر الاتصال بالخادم"; } finally { setBusy(false); } };
  const downloadBackup = () => { downloadFile(`mikhail-backup-${today()}.json`, JSON.stringify({ version: 1, exportedAt: new Date().toISOString(), data }, null, 2), "application/json;charset=utf-8"); notify("تم تنزيل النسخة الاحتياطية"); };
  const restoreBackup = async (file: File) => {
    if (!authenticated) { open({ type: "login" }); return; }
    if (file.size > 15 * 1024 * 1024) { notify("حجم النسخة الاحتياطية أكبر من 15 ميجابايت", true); return; }
    if (!window.confirm("ستستبدل الاستعادة جميع البيانات الحالية بالنسخة المختارة. يُنصح بتنزيل نسخة احتياطية أولاً. هل تريد المتابعة؟")) return;
    try { const backup = JSON.parse(await file.text()); if (!backup || backup.version !== 1 || !backup.data) throw new Error("ملف النسخة الاحتياطية غير صالح"); if (await onAction("restoreBackup", { backup })) notify("تمت استعادة النسخة الاحتياطية بنجاح"); }
    catch { notify("تعذر قراءة النسخة الاحتياطية. تأكد من اختيار ملف JSON صحيح.", true); }
  };
  const exportCSV = () => { const rows: (string | number)[][] = [["اسم الطالب", "الصف الدراسي", "الهاتف", "المجموعات", "الاشتراك المستحق", "المدفوع", "المتبقي", "الحالة", "ملاحظات"]]; data.students.forEach(s => { const balance = studentBalance(data, s.id, month); rows.push([s.name, s.grade, s.phone, data.memberships.filter(m => m.studentId === s.id).map(m => data.groups.find(g => g.id === m.groupId)?.name || "").join(" / "), balance.due, balance.paid, balance.remaining, statusInfo(balance.status,balance.due).label, s.notes]); }); const csv = rows.map(r => r.map(v => { const value = String(v); const safe = /^[=+\-@\t\r]/.test(value) ? `'${value}` : value; return `"${safe.replace(/"/g, '""')}"`; }).join(",")).join("\r\n"); downloadFile(`students-${month}.csv`, `\ufeff${csv}`, "text/csv;charset=utf-8"); notify("تم تنزيل ملف متوافق مع Excel"); };
  const printReport = () => { const income = data.payments.filter(p => p.paymentDate.startsWith(month)).reduce((n,p) => n+p.amount,0); const expenses = data.expenses.filter(e => e.expenseDate.startsWith(month)).reduce((n,e) => n+e.amount,0); const popup = window.open("", "_blank"); if (!popup) { notify("يرجى السماح بالنوافذ المنبثقة للطباعة", true); return; } const rows = data.students.map(s => { const b = studentBalance(data,s.id,month); return `<tr><td>${escapeHTML(s.name)}</td><td>${escapeHTML(s.grade)}</td><td>${escapeHTML(statusInfo(b.status,b.due).label)}</td><td>${b.remaining}</td></tr>`; }).join(""); popup.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>تقرير مستر ميخائيل</title><style>body{font-family:Arial,sans-serif;padding:36px;color:#1b2c48}h1{color:#255dd9}table{border-collapse:collapse;width:100%;margin-top:25px}th,td{border:1px solid #ddd;padding:10px;text-align:right}th{background:#eef4ff}.stats{display:flex;gap:30px;margin:25px 0}small{color:#667}</style></head><body><h1>تقرير إدارة الدروس</h1><p>مستر ميخائيل توما — ${escapeHTML(monthLabel(month))}</p><div class="stats"><div>الإيرادات: <b>${income} ج.م</b></div><div>المصروفات: <b>${expenses} ج.م</b></div><div>صافي الربح: <b>${income-expenses} ج.م</b></div></div><h2>حالة اشتراكات الطلاب</h2><table><thead><tr><th>الطالب</th><th>الصف</th><th>الحالة</th><th>المتبقي</th></tr></thead><tbody>${rows}</tbody></table><p><small>تم إنشاء التقرير من لوحة إدارة الدروس.</small></p><script>window.onload=function(){window.print()}<\/script></body></html>`); popup.document.close(); };
  const context: Ctx = { data, month, setMonth, search, setSearch, setView, groupId, setGroupId, open, remove, downloadBackup, restoreBackup, exportCSV, printReport, authenticated, busy, logout: () => { void logout(); } };
  const unpaid = data.students.filter(s => { const b = studentBalance(data,s.id,month); return b.due > 0 && b.remaining > 0; }).length;
  const todaysGroups = data.groups.filter(g => g.day === new Date().getDay()).length;
  return <AppContext.Provider value={context}><div className="app-shell" dir="rtl">
    {sidebar && <div className="sidebar-backdrop" onClick={() => setSidebar(false)}/>}
    <aside className={`sidebar ${sidebar ? "sidebar-open" : ""}`}><div className="brand"><div className="brand-mark"><GraduationCap size={25}/></div><div><strong>مستر ميخائيل توما</strong><span>TEACHER DASHBOARD</span></div><button className="sidebar-close icon-button" onClick={() => setSidebar(false)} aria-label="إغلاق القائمة"><X size={18}/></button></div>
      <div className="sidebar-scroll"><div className="nav-label">القائمة الرئيسية</div><nav className="navigation">{nav.map(item => <button key={item.view} className={`nav-link ${view === item.view || (view === "group" && item.view === "groups") ? "active" : ""}`} onClick={() => setView(item.view)}><item.icon size={19} strokeWidth={1.8}/><span>{item.label}</span>{item.view === "dashboard" && <span className="nav-active-dot"/>}</button>)}</nav><div className="nav-label nav-label-second">الحساب</div><nav className="navigation"><button className={`nav-link ${view === "settings" ? "active" : ""}`} onClick={() => setView("settings")}><Settings2 size={19}/><span>الإعدادات</span></button><button className="nav-link" onClick={downloadBackup}><Download size={19}/><span>نسخة احتياطية</span></button></nav></div>
      <div className="sidebar-bottom"><div className="sidebar-tip"><div className="tip-icon"><Sparkles size={16}/></div><strong>كل شيء في مكان واحد</strong><p>نظّم دروسك وركّز على ما يهمك.</p><button onClick={() => setView("analytics")}>استكشف التقارير <ChevronLeft size={13}/></button></div><button className="sidebar-profile" onClick={() => authenticated ? setView("settings") : open({ type: "login" })}><span className="teacher-avatar">MT</span><span><strong>مستر ميخائيل توما</strong><small>{authenticated ? "حساب المعلم" : "الوضع التجريبي"}</small></span><MoreHorizontal size={18}/></button></div>
    </aside>
    <div className="workspace"><header className="topbar"><div className="topbar-title"><button className="mobile-menu icon-button" onClick={() => setSidebar(true)} aria-label="فتح القائمة"><Menu size={21}/></button><span className="breadcrumb-icon"><LayoutDashboard size={16}/></span><span className="breadcrumb-muted">الرئيسية</span><ChevronLeft size={14} className="breadcrumb-chevron"/><strong>{pageNames[view]}</strong></div><div className="topbar-actions"><div className="global-search"><Search size={18}/><input ref={searchRef} aria-label="البحث عن طالب" placeholder="ابحث عن طالب، مجموعة..." value={search} onChange={e => { setSearch(e.target.value); if (e.target.value) setView("students"); }}/><kbd>⌘ K</kbd></div><div className="notification-wrap"><button className="top-icon" onClick={() => setBell(!bell)} aria-label="الإشعارات"><Bell size={19}/>{(unpaid > 0 || todaysGroups > 0) && <i/>}</button>{bell && <div className="notification-popover"><strong>نظرة سريعة</strong><button onClick={() => { setView("payments"); setBell(false); }}><span className="notification-dot orange"/> {unpaid} طلاب لديهم اشتراكات متبقية</button><button onClick={() => { setView("groups"); setBell(false); }}><span className="notification-dot blue"/> {todaysGroups} مجموعات في جدول اليوم</button></div>}</div><span className="topbar-divider"/><button className="header-profile" onClick={() => authenticated ? setView("settings") : open({ type: "login" })}><span className="teacher-avatar">MT</span><span><strong>مستر ميخائيل</strong><small>{authenticated ? "المعلم" : "معاينة تجريبية"}</small></span><ChevronDown size={15}/></button></div></header>
      <main className="main-content">{!authenticated && <div className="demo-strip"><div><span className="demo-dot"/><strong>أنت تتصفح بيانات تجريبية</strong><span>سجّل الدخول للوصول إلى بياناتك وحفظ التغييرات.</span></div><button onClick={() => open({ type: "login" })}>تسجيل الدخول <ArrowLeft size={14}/></button></div>}
        {view === "dashboard" && <DashboardView/>}{view === "students" && <StudentsView/>}{view === "groups" && <GroupsView/>}{view === "group" && <GroupView/>}{view === "attendance" && <AttendanceView/>}{view === "payments" && <PaymentsView/>}{view === "expenses" && <ExpensesView/>}{view === "homework" && <HomeworkView/>}{view === "analytics" && <AnalyticsView/>}{view === "settings" && <SettingsView/>}
      </main><footer className="footer"><span>© {new Date().getFullYear()} مستر ميخائيل توما. صُنع لتنظيم يومك بشكل أفضل.</span><span>لوحة إدارة الدروس <i/> الإصدار ١.٠</span></footer></div>
    {modal && <ModalRenderer key={`${modal.type}-${"item" in modal ? modal.item?.id || "new" : "studentId" in modal ? modal.studentId || "new" : "groupId" in modal ? modal.groupId || "new" : "assignmentId" in modal ? modal.assignmentId : ""}`} modal={modal} data={data} month={month} busy={busy} demoCredentials={showDemoCredentials} onClose={() => setModal(null)} onOpen={open} onAction={onAction} onLogin={onLogin} onPassword={onPassword}/>}
    {toast && <div className={`toast ${toast.error ? "toast-error" : ""}`}>{toast.error ? <AlertCircle size={18}/> : <CheckCircle2 size={18}/>}<span>{toast.text}</span><button onClick={() => setToast(null)}><X size={15}/></button></div>}
  </div></AppContext.Provider>;
}

function DashboardView() {
  const { data, month, setMonth, setView, setGroupId, open } = useApp();
  const income = data.payments.filter(p => p.paymentDate.startsWith(month)).reduce((n,p) => n+p.amount,0); const expenses = data.expenses.filter(e => e.expenseDate.startsWith(month)).reduce((n,e) => n+e.amount,0); const records = data.attendance.filter(a => a.lessonDate.startsWith(month)); const present = records.filter(a => a.status === "present").length; const attendanceRate = records.length ? Math.round(present / records.length * 100) : 0; const groupsToday = data.groups.filter(g => g.day === new Date().getDay()).sort((a,b) => a.time.localeCompare(b.time));
  const stats = [
    { label: "إجمالي الطلاب", value: String(data.students.length), sub: "طالب مسجل", icon: UsersRound, color: "blue" },
    { label: "المجموعات", value: String(data.groups.length), sub: "مجموعة دراسية", icon: Layers3, color: "purple" },
    { label: "إيرادات الشهر", value: formatMoney(income), unit: "ج.م", sub: "المدفوعات المحصّلة", icon: TrendingUp, color: "green" },
    { label: "مصروفات الشهر", value: formatMoney(expenses), unit: "ج.م", sub: "إجمالي المصروفات", icon: TrendingDown, color: "orange" },
    { label: "صافي الربح", value: formatMoney(income-expenses), unit: "ج.م", sub: "بعد خصم المصروفات", icon: Wallet, color: "indigo" },
  ];
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-dot"/> نظرة عامة على نشاطك</div><h1>أهلاً بك، مستر ميخائيل <span>👋</span></h1><p>كل ما تحتاجه لإدارة دروسك في مكان واحد. نتمنى لك يوماً موفقاً!</p></div><div className="welcome-actions"><MonthInput value={month} onChange={setMonth}/><button className="button button-primary" onClick={() => open({ type: "student" }, true)}><Plus size={18}/> إضافة طالب</button></div></div>
    <div className="stats-grid">{stats.map(item => <div className="stat-card" key={item.label}><div className="stat-top"><span>{item.label}</span><div className={`stat-icon ${item.color}`}><item.icon size={20} strokeWidth={1.9}/></div></div><div className="stat-value">{item.value} {item.unit && <small>{item.unit}</small>}</div><div className="stat-sub"><span className={`tiny-dot ${item.color}`}/>{item.sub}</div></div>)}</div>
    <div className="dashboard-grid top-grid"><section className="card finance-card"><SectionHeading title="نظرة على الحسابات" subtitle="تابع الإيرادات والمصروفات خلال الأشهر الماضية"><span className="subtle-pill"><CalendarDays size={14}/> آخر ٦ أشهر</span></SectionHeading><div className="chart-legend"><span><i className="blue-dot"/> الإيرادات</span><span><i className="green-dot"/> المصروفات</span></div><FinanceChart data={data}/></section><section className="card subscriptions-card"><SectionHeading title="حالة الاشتراكات" subtitle={`ملخص المدفوعات · ${monthLabel(month)}`}><button className="dots-button" onClick={() => setView("payments")} aria-label="عرض المدفوعات"><MoreHorizontal size={20}/></button></SectionHeading><PaymentDonut data={data} month={month}/><button className="card-bottom-link" onClick={() => setView("payments")}>عرض تفاصيل المدفوعات <ChevronLeft size={15}/></button></section></div>
    <div className="dashboard-grid bottom-grid"><section className="card schedule-card"><SectionHeading title="حصص اليوم" subtitle="جدول المجموعات والمواعيد القادمة"><button className="text-link" onClick={() => setView("groups")}>عرض المجموعات <ChevronLeft size={14}/></button></SectionHeading><div className="schedule-date"><CalendarDays size={15}/><span>{formatDate(today(), { weekday: "long", day: "numeric", month: "long" })}</span><span className="schedule-count">{groupsToday.length} حصص</span></div><div className="schedule-list">{groupsToday.length ? groupsToday.map((g,i) => <button className="schedule-item" key={g.id} onClick={() => { setGroupId(g.id); setView("group"); }}><div className={`group-icon ${groupColor(g.color)}`}><BookOpen size={19}/></div><div className="schedule-name"><strong>{g.name}</strong><span>{g.subject} <i/> {data.memberships.filter(m => m.groupId === g.id).length} طلاب</span></div><div className="schedule-time"><strong>{timeLabel(g.time)}</strong><span>{g.duration} دقيقة</span></div><ChevronLeft size={17} className="faint"/></button>) : <div className="empty-inline">لا توجد حصص مجدولة اليوم. يوم هادئ!</div>}</div></section><section className="card attendance-overview"><SectionHeading title="نظرة على الحضور" subtitle={`ملخص الحضور خلال ${monthLabel(month)}`}><button className="dots-button" onClick={() => setView("attendance")} aria-label="عرض الحضور"><MoreHorizontal size={20}/></button></SectionHeading><div className="attendance-summary"><div className="attendance-ring" style={{ background: `conic-gradient(#3f78ed ${attendanceRate * 3.6}deg, #eaf0fa 0deg)` }}><div><strong>{attendanceRate}%</strong><span>معدل الحضور</span></div></div><div className="attendance-numbers"><div><span><i className="blue-dot"/> الحضور</span><strong>{present} <small>سجل</small></strong></div><div><span><i className="orange-dot"/> الغياب</span><strong>{records.length - present} <small>سجل</small></strong></div></div></div><button className="attendance-action" onClick={() => open({ type: "attendance" }, true)}><CalendarCheck size={16}/> تسجيل حضور اليوم <ChevronLeft size={15}/></button></section></div>
    <section className="card recent-card"><SectionHeading title="الطلاب المسجلون" subtitle="متابعة سريعة لأحدث بيانات الطلاب"><button className="text-link" onClick={() => setView("students")}>عرض كل الطلاب <ChevronLeft size={14}/></button></SectionHeading><StudentTable students={data.students.slice(0,5)} compact/></section>
  </>;
}

function StudentTable({ students, compact = false }: { students: Student[]; compact?: boolean }) {
  const { data, month, open, remove } = useApp();
  if (!students.length) return <Empty title="لا يوجد طلاب" text="جرّب تغيير البحث أو أضف طالباً جديداً." icon={UsersRound}/>;
  return <div className="table-scroll"><table className="data-table"><thead><tr><th>الطالب</th><th>الصف الدراسي</th><th>المجموعة</th><th>رقم الهاتف</th><th>حالة الاشتراك</th><th>{compact ? "" : "الإجراءات"}</th></tr></thead><tbody>{students.map((s,i) => { const balance = studentBalance(data,s.id,month); const groups = data.memberships.filter(m => m.studentId === s.id).map(m => data.groups.find(g => g.id === m.groupId)?.name).filter(Boolean); return <tr key={s.id}><td><button className="table-person" onClick={() => open({ type: "profile", studentId: s.id })}><Avatar name={s.name} index={i}/><span><strong>{s.name}</strong><small>#{String(s.id).padStart(4,"0")}</small></span></button></td><td>{s.grade}</td><td><span className="group-table-label">{groups[0] || "—"}</span>{groups.length > 1 && <small className="extra-groups"> +{groups.length-1}</small>}</td><td className="phone-cell" dir="ltr">{s.phone || "—"}</td><td><Status status={balance.status} due={balance.due}/></td><td><div className="row-actions"><button onClick={() => open({ type: "profile", studentId: s.id })} aria-label="عرض الطالب" title="عرض الملف"><Eye size={16}/></button>{!compact && <><button onClick={() => open({ type: "student", item: s }, true)} aria-label="تعديل الطالب" title="تعديل"><Pencil size={15}/></button><button className="danger-action" onClick={() => remove("deleteStudent", s.id, "هل تريد حذف الطالب وجميع سجلاته نهائياً؟")} aria-label="حذف الطالب" title="حذف"><Trash2 size={15}/></button></>}</div></td></tr>; })}</tbody></table></div>;
}
function StudentsView() {
  const { data, month, search, setSearch, open, exportCSV } = useApp(); const [group, setGroup] = useState(0); const [filter, setFilter] = useState("all");
  const filtered = data.students.filter(s => { const matchesText = !search || s.name.toLowerCase().includes(search.toLowerCase()) || s.grade.includes(search) || data.memberships.filter(m => m.studentId === s.id).some(m => data.groups.find(g => g.id === m.groupId)?.name.includes(search)); const balance = studentBalance(data,s.id,month); const absences = data.attendance.filter(a => a.studentId === s.id && a.status === "absent").length; const incomplete = data.assignments.some(a => { if (!data.memberships.some(m => m.studentId === s.id && m.groupId === a.groupId)) return false; const p = data.progress.find(p => p.studentId === s.id && p.assignmentId === a.id); return (!!a.homework && p?.homeworkStatus !== "completed") || (!!a.memorization && p?.memorizationStatus !== "completed"); }); return matchesText && (!group || data.memberships.some(m => m.studentId === s.id && m.groupId === group)) && (filter === "all" || (filter === "paid" && balance.status === "paid") || (filter === "unpaid" && balance.due > 0 && balance.remaining > 0) || (filter === "absent" && absences >= 2) || (filter === "homework" && incomplete)); });
  return <><PageHeading eyebrow="إدارة الطلاب" title="الطلاب" description="كل تفاصيل طلابك ومتابعتهم في مكان واحد."><button className="button button-light" onClick={exportCSV}><Download size={16}/> تصدير Excel</button><button className="button button-primary" onClick={() => open({ type: "student" }, true)}><Plus size={17}/> إضافة طالب</button></PageHeading><div className="page-summary-row"><div><span className="summary-icon blue"><UsersRound size={19}/></span><span><small>إجمالي الطلاب</small><strong>{data.students.length} طالب</strong></span></div><div><span className="summary-icon green"><CheckCircle2 size={19}/></span><span><small>المسددون هذا الشهر</small><strong>{data.students.filter(s => studentBalance(data,s.id,month).status === "paid").length} طالب</strong></span></div><div><span className="summary-icon orange"><AlertCircle size={19}/></span><span><small>لديهم مبالغ متبقية</small><strong>{data.students.filter(s => { const b=studentBalance(data,s.id,month); return b.due > 0 && b.remaining > 0; }).length} طالب</strong></span></div></div><section className="card list-card"><SectionHeading title="قائمة الطلاب" subtitle={`${filtered.length} طالب في القائمة`}><div className="filter-row"><div className="input-search"><Search size={16}/><input placeholder="ابحث عن طالب..." value={search} onChange={e => setSearch(e.target.value)}/></div><select aria-label="تصفية حسب المجموعة" value={group} onChange={e => setGroup(Number(e.target.value))}><option value={0}>كل المجموعات</option>{data.groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select><select aria-label="تصفية الطلاب" value={filter} onChange={e => setFilter(e.target.value)}><option value="all">كل الحالات</option><option value="paid">الاشتراك مدفوع</option><option value="unpaid">اشتراك غير مكتمل</option><option value="absent">غياب متكرر</option><option value="homework">واجب أو حفظ غير مكتمل</option></select></div></SectionHeading><StudentTable students={filtered}/></section></>;
}
function GroupsView() {
  const { data, month, open, setGroupId, setView, remove } = useApp();
  return <><PageHeading eyebrow="تنظيم الدروس" title="المجموعات الدراسية" description="نظّم مجموعاتك، طلابك ومواعيد حصصك بسهولة."><button className="button button-primary" onClick={() => open({ type: "group" }, true)}><Plus size={17}/> إضافة مجموعة</button></PageHeading><div className="list-intro"><span>جميع المجموعات <b>{data.groups.length}</b></span><span>اضغط على المجموعة لعرض تفاصيلها</span></div>{data.groups.length ? <div className="groups-grid">{data.groups.map(g => { const members = data.memberships.filter(m => m.groupId === g.id); const paid = members.filter(m => paidFor(data,m.studentId,g.id,month) >= m.fee && m.fee > 0).length; return <article className="card group-card" key={g.id}><div className="group-card-top"><span className={`group-icon group-icon-lg ${groupColor(g.color)}`}><BookOpen size={22}/></span><div className="row-actions"><button onClick={() => open({ type: "group", item:g }, true)} aria-label="تعديل المجموعة"><Pencil size={16}/></button><button className="danger-action" onClick={() => remove("deleteGroup",g.id,"حذف المجموعة سيحذف حضورها ودفعاتها وواجباتها. هل أنت متأكد؟")} aria-label="حذف المجموعة"><Trash2 size={16}/></button></div></div><button className="group-card-title" onClick={() => { setGroupId(g.id); setView("group"); }}><h3>{g.name}</h3><p>{g.grade} · {g.subject}</p></button><div className="group-meta"><span><CalendarDays size={16}/>{days[g.day]}</span><span><Clock3 size={16}/>{timeLabel(g.time)}</span><span><UsersRound size={16}/>{members.length} طلاب</span></div><div className="group-card-footer"><div><span>الاشتراك الشهري</span><strong>{money(g.monthlyFee)}</strong></div><div><span>المسددون</span><strong>{paid} / {members.length}</strong></div><button onClick={() => { setGroupId(g.id); setView("group"); }} aria-label="تفاصيل المجموعة"><ChevronLeft size={18}/></button></div></article>; })}</div> : <section className="card"><Empty title="لا توجد مجموعات بعد" text="أنشئ أول مجموعة لتنظيم طلابك وحصصك." icon={Layers3} action={<button className="button button-primary" onClick={() => open({ type:"group" },true)}>إضافة مجموعة</button>}/></section>}</>;
}
function GroupView() {
  const { data, month, groupId, setView, open } = useApp(); const [tab, setTab] = useState("students"); const group = data.groups.find(g => g.id === groupId);
  if (!group) return <Empty title="المجموعة غير موجودة" text="اختر مجموعة من القائمة." icon={Layers3} action={<button className="button button-light" onClick={() => setView("groups")}>العودة للمجموعات</button>}/>;
  const members = data.memberships.filter(m => m.groupId === group.id); const paid = members.filter(m => m.fee > 0 && paidFor(data,m.studentId,group.id,month) >= m.fee).length;
  return <><button className="back-link" onClick={() => setView("groups")}><ArrowLeft size={15}/> العودة إلى المجموعات</button><PageHeading eyebrow="تفاصيل المجموعة" title={group.name} description={`${group.subject} · ${group.grade} · ${days[group.day]} ${timeLabel(group.time)}`}><button className="button button-light" onClick={() => open({ type:"group", item:group },true)}><Pencil size={15}/> تعديل المجموعة</button><button className="button button-primary" onClick={() => open({ type:"attendance", groupId:group.id },true)}><CalendarCheck size={16}/> تسجيل الحضور</button></PageHeading><div className="page-summary-row"><div><span className="summary-icon blue"><UsersRound size={19}/></span><span><small>طلاب المجموعة</small><strong>{members.length} طالب</strong></span></div><div><span className="summary-icon purple"><CalendarDays size={19}/></span><span><small>موعد الحصة</small><strong>{days[group.day]} · {timeLabel(group.time)}</strong></span></div><div><span className="summary-icon green"><CreditCard size={19}/></span><span><small>المسددون في {monthLabel(month)}</small><strong>{paid} من {members.length}</strong></span></div></div><div className="tabs">{[["students","الطلاب"],["attendance","الحضور والغياب"],["payments","المدفوعات"],["homework","الواجب والحفظ"]].map(([id,label]) => <button className={tab === id ? "active" : ""} key={id} onClick={() => setTab(id)}>{label}</button>)}</div>{tab === "students" && <section className="card list-card"><SectionHeading title="طلاب المجموعة" subtitle={`${members.length} طالب مسجل`}><button className="button button-light button-small" onClick={() => open({ type:"group", item:group },true)}><Plus size={15}/> إدارة الطلاب</button></SectionHeading><StudentTable students={data.students.filter(s => members.some(m => m.studentId === s.id))}/></section>}{tab === "attendance" && <AttendanceView scope={group.id} embedded/>}{tab === "payments" && <PaymentsView scope={group.id} embedded/>}{tab === "homework" && <HomeworkView scope={group.id} embedded/>}</>;
}
function AttendanceView({ scope, embedded = false }: { scope?: number; embedded?: boolean }) {
  const { data, month, setMonth, open } = useApp(); const [selected, setSelected] = useState(scope || 0); const selectedGroup = scope || selected; const records = data.attendance.filter(a => a.lessonDate.startsWith(month) && (!selectedGroup || a.groupId === selectedGroup));
  const lessons = Array.from(new Set(records.map(a => `${a.groupId}|${a.lessonDate}`))).map(key => { const [g,d] = key.split("|"); const groupId = Number(g); const list = records.filter(a => a.groupId === groupId && a.lessonDate === d); return { key, groupId, date:d, total:list.length, present:list.filter(a => a.status === "present").length }; }).sort((a,b) => b.date.localeCompare(a.date));
  const present = records.filter(a => a.status === "present").length;
  return <>{!embedded && <PageHeading eyebrow="متابعة الحصص" title="الحضور والغياب" description="سجّل الحضور وتابع غياب الطلاب في كل حصة."><button className="button button-primary" onClick={() => open({ type:"attendance", groupId:selectedGroup || undefined },true)}><Plus size={17}/> تسجيل الحضور</button></PageHeading>}<div className="page-summary-row"><div><span className="summary-icon blue"><CalendarCheck size={19}/></span><span><small>الحصص المسجلة</small><strong>{lessons.length} حصة</strong></span></div><div><span className="summary-icon green"><CheckCircle2 size={19}/></span><span><small>سجلات الحضور</small><strong>{present} سجل</strong></span></div><div><span className="summary-icon orange"><AlertCircle size={19}/></span><span><small>سجلات الغياب</small><strong>{records.length-present} سجل</strong></span></div></div><section className="card list-card"><SectionHeading title="سجل الحصص" subtitle="اختر حصة لتعديل حضور الطلاب"><div className="filter-row">{!scope && <select aria-label="المجموعة" value={selected} onChange={e => setSelected(Number(e.target.value))}><option value={0}>كل المجموعات</option>{data.groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>}<MonthInput value={month} onChange={setMonth}/><button className="button button-light button-small" onClick={() => open({ type:"attendance", groupId:selectedGroup || undefined },true)}><Plus size={15}/> تسجيل حصة</button></div></SectionHeading>{lessons.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>تاريخ الحصة</th><th>المجموعة</th><th>عدد الطلاب</th><th>حاضر</th><th>غائب</th><th>الإجراءات</th></tr></thead><tbody>{lessons.map(l => <tr key={l.key}><td><strong>{formatDate(l.date)}</strong></td><td>{data.groups.find(g => g.id === l.groupId)?.name}</td><td>{l.total}</td><td><span className="status status-paid">{l.present} حاضر</span></td><td><span className="status status-unpaid">{l.total-l.present} غائب</span></td><td><button className="text-link" onClick={() => open({ type:"attendance", groupId:l.groupId, lessonDate:l.date },true)}><Pencil size={14}/> تعديل</button></td></tr>)}</tbody></table></div> : <Empty title="لا توجد حصص مسجلة" text="ابدأ بتسجيل حضور المجموعة في أول حصة." icon={CalendarCheck}/>}</section></>;
}
function PaymentsView({ scope, embedded = false }: { scope?: number; embedded?: boolean }) {
  const { data, month, setMonth, open, remove } = useApp(); const [selected, setSelected] = useState(scope || 0); const [status, setStatus] = useState("all"); const group = scope || selected;
  const members = data.memberships.filter(m => !group || m.groupId === group).map(m => { const student = data.students.find(s => s.id === m.studentId); const g = data.groups.find(g => g.id === m.groupId); const paid = paidFor(data,m.studentId,m.groupId,month); return { ...m, student, group:g, paid, remaining:Math.max(0,m.fee-paid), status: m.fee > 0 && paid >= m.fee ? "paid" : paid > 0 ? "partial" : "unpaid" }; }).filter(m => m.student && m.group && (status === "all" || (status === "unpaid" ? m.remaining > 0 : m.status === status)));
  const monthPayments = data.payments.filter(p => p.month === month && (!group || p.groupId === group)).sort((a,b) => b.paymentDate.localeCompare(a.paymentDate)); const outstanding = data.memberships.filter(m => !group || m.groupId === group).reduce((n,m) => n + Math.max(0,m.fee-paidFor(data,m.studentId,m.groupId,month)),0);
  return <>{!embedded && <PageHeading eyebrow="الحسابات والاشتراكات" title="المدفوعات" description="تابع الاشتراكات، الدفعات الجزئية والمبالغ المتبقية."><button className="button button-primary" onClick={() => open({ type:"payment", groupId:group || undefined },true)}><Plus size={17}/> تسجيل دفعة</button></PageHeading>}<div className="page-summary-row"><div><span className="summary-icon green"><Wallet size={19}/></span><span><small>المحصّل لاشتراكات الشهر</small><strong>{money(monthPayments.reduce((n,p) => n+p.amount,0))}</strong></span></div><div><span className="summary-icon orange"><AlertCircle size={19}/></span><span><small>إجمالي المستحقات المتبقية</small><strong>{money(outstanding)}</strong></span></div><div><span className="summary-icon blue"><CreditCard size={19}/></span><span><small>عدد الدفعات</small><strong>{monthPayments.length} دفعة</strong></span></div></div><section className="card list-card"><SectionHeading title="حالة الاشتراكات" subtitle="حالة كل طالب في كل مجموعة بشكل منفصل"><div className="filter-row">{!scope && <select aria-label="المجموعة" value={selected} onChange={e => setSelected(Number(e.target.value))}><option value={0}>كل المجموعات</option>{data.groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>}<select aria-label="حالة الدفع" value={status} onChange={e => setStatus(e.target.value)}><option value="all">كل الحالات</option><option value="paid">مدفوع</option><option value="unpaid">لم يكتمل الدفع</option><option value="partial">مدفوع جزئياً</option></select><MonthInput value={month} onChange={setMonth}/><button className="button button-light button-small" onClick={() => open({ type:"payment", groupId:group || undefined },true)}><Plus size={15}/> دفعة</button></div></SectionHeading>{members.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>الطالب</th><th>المجموعة</th><th>المستحق</th><th>المدفوع</th><th>المتبقي</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody>{members.map((m,i) => <tr key={m.id}><td><button className="table-person" onClick={() => open({ type:"profile", studentId:m.studentId })}><Avatar name={m.student!.name} index={i}/><strong>{m.student!.name}</strong></button></td><td>{m.group!.name}</td><td>{money(m.fee)}</td><td>{money(m.paid)}</td><td><strong>{money(m.remaining)}</strong></td><td><Status status={m.status} due={m.fee}/></td><td>{m.remaining > 0 && <button className="text-link" onClick={() => open({ type:"payment", studentId:m.studentId, groupId:m.groupId },true)}><Plus size={14}/> دفعة</button>}</td></tr>)}</tbody></table></div> : <Empty title="لا توجد اشتراكات مطابقة" text="أضف طلاباً إلى مجموعة أو غيّر التصفية." icon={Wallet}/>}</section><section className="card list-card section-spaced"><SectionHeading title="سجل الدفعات" subtitle={`دفعات اشتراك ${monthLabel(month)}`}/>{monthPayments.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>تاريخ الدفع</th><th>الطالب</th><th>المجموعة</th><th>المبلغ</th><th>ملاحظات</th><th>الإجراءات</th></tr></thead><tbody>{monthPayments.map(p => <tr key={p.id}><td>{formatDate(p.paymentDate)}</td><td><strong>{data.students.find(s => s.id === p.studentId)?.name || "—"}</strong></td><td>{data.groups.find(g => g.id === p.groupId)?.name || "—"}</td><td><strong>{money(p.amount)}</strong></td><td>{p.notes || "—"}</td><td><div className="row-actions"><button onClick={() => open({ type:"payment", item:p },true)} aria-label="تعديل الدفعة"><Pencil size={15}/></button><button className="danger-action" onClick={() => remove("deletePayment",p.id,"هل تريد حذف هذه الدفعة؟")} aria-label="حذف الدفعة"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div> : <Empty title="لا توجد دفعات في هذا الشهر" text="ستظهر الدفعات المسجلة هنا." icon={CreditCard}/>}</section></>;
}
function ExpensesView() {
  const { data, month, setMonth, open, remove } = useApp(); const [category, setCategory] = useState("all"); const expenses = data.expenses.filter(e => e.expenseDate.startsWith(month) && (category === "all" || e.category === category)).sort((a,b) => b.expenseDate.localeCompare(a.expenseDate));
  return <><PageHeading eyebrow="إدارة المصروفات" title="المصروفات" description="سجّل مصروفاتك اليومية وتابع أين تذهب ميزانيتك."><button className="button button-primary" onClick={() => open({ type:"expense" },true)}><Plus size={17}/> إضافة مصروف</button></PageHeading><div className="page-summary-row"><div><span className="summary-icon orange"><ReceiptText size={19}/></span><span><small>مصروفات {monthLabel(month)}</small><strong>{money(data.expenses.filter(e => e.expenseDate.startsWith(month)).reduce((n,e) => n+e.amount,0))}</strong></span></div><div><span className="summary-icon purple"><Layers3 size={19}/></span><span><small>العمليات المسجلة</small><strong>{data.expenses.filter(e => e.expenseDate.startsWith(month)).length} عملية</strong></span></div><div><span className="summary-icon blue"><TrendingUp size={19}/></span><span><small>إيرادات الشهر</small><strong>{money(data.payments.filter(p => p.paymentDate.startsWith(month)).reduce((n,p) => n+p.amount,0))}</strong></span></div></div><div className="expense-layout"><section className="card list-card"><SectionHeading title="سجل المصروفات" subtitle="جميع المصروفات حسب التاريخ والتصنيف"><div className="filter-row"><select value={category} onChange={e => setCategory(e.target.value)} aria-label="تصنيف المصروف"><option value="all">كل التصنيفات</option>{["المواصلات","الطباعة","الأدوات التعليمية","الإيجار","أخرى"].map(c => <option key={c}>{c}</option>)}</select><MonthInput value={month} onChange={setMonth}/></div></SectionHeading>{expenses.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>الوصف</th><th>التصنيف</th><th>التاريخ</th><th>المبلغ</th><th>الإجراءات</th></tr></thead><tbody>{expenses.map(e => <tr key={e.id}><td><strong>{e.description}</strong></td><td><span className="tag">{e.category}</span></td><td>{formatDate(e.expenseDate)}</td><td><strong>{money(e.amount)}</strong></td><td><div className="row-actions"><button onClick={() => open({ type:"expense", item:e },true)} aria-label="تعديل المصروف"><Pencil size={15}/></button><button className="danger-action" onClick={() => remove("deleteExpense",e.id,"هل تريد حذف هذا المصروف؟")} aria-label="حذف المصروف"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div> : <Empty title="لا توجد مصروفات" text="لم تسجل مصروفات لهذا الاختيار." icon={ReceiptText}/>}</section><section className="card"><SectionHeading title="توزيع المصروفات" subtitle="حسب التصنيف لهذا الشهر"/><ExpenseChart data={data} month={month}/></section></div></>;
}
function HomeworkView({ scope, embedded = false }: { scope?: number; embedded?: boolean }) {
  const { data, open, remove } = useApp(); const [selected,setSelected] = useState(scope || 0); const group = scope || selected; const assignments = data.assignments.filter(a => !group || a.groupId === group).sort((a,b) => b.lessonDate.localeCompare(a.lessonDate));
  return <>{!embedded && <PageHeading eyebrow="متابعة التقدم" title="الواجب والحفظ" description="خطط لكل حصة وتابع إنجاز الطلاب بشكل منفصل لكل مجموعة."><button className="button button-primary" onClick={() => open({ type:"assignment", groupId:group || undefined },true)}><Plus size={17}/> إضافة واجب</button></PageHeading>}<section className="card list-card"><SectionHeading title="سجل الواجبات والحفظ" subtitle={`${assignments.length} حصة مسجلة`}><div className="filter-row">{!scope && <select value={selected} onChange={e => setSelected(Number(e.target.value))} aria-label="المجموعة"><option value={0}>كل المجموعات</option>{data.groups.map(g => <option value={g.id} key={g.id}>{g.name}</option>)}</select>}<button className="button button-light button-small" onClick={() => open({ type:"assignment", groupId:group || undefined },true)}><Plus size={15}/> إضافة واجب</button></div></SectionHeading>{assignments.length ? <div className="assignments-list">{assignments.map(a => { const g = data.groups.find(g => g.id === a.groupId); const students = data.memberships.filter(m => m.groupId === a.groupId).length; const completed = data.progress.filter(p => p.assignmentId === a.id && data.memberships.some(m => m.studentId === p.studentId && m.groupId === a.groupId) && (!a.homework || p.homeworkStatus === "completed") && (!a.memorization || p.memorizationStatus === "completed")).length; return <article className="assignment-card" key={a.id}><div className="assignment-top"><div className={`group-icon ${groupColor(g?.color || "blue")}`}><BookOpen size={19}/></div><div><strong>{g?.name || "المجموعة"}</strong><span>{formatDate(a.lessonDate)} · {g?.subject}</span></div><div className="row-actions"><button onClick={() => open({ type:"assignment", item:a },true)} aria-label="تعديل الواجب"><Pencil size={15}/></button><button className="danger-action" onClick={() => remove("deleteAssignment",a.id,"هل تريد حذف هذا الواجب ومتابعته؟")} aria-label="حذف الواجب"><Trash2 size={15}/></button></div></div><div className="assignment-content"><div><span>الواجب المطلوب</span><p>{a.homework || "—"}</p></div><div><span>الحفظ المطلوب</span><p>{a.memorization || "—"}</p></div></div><div className="assignment-footer"><span><CheckCircle2 size={15}/> {completed} من {students} أكملوا الواجب والحفظ</span><button className="text-link" onClick={() => open({ type:"progress", assignmentId:a.id },true)}>متابعة إنجاز الطلاب <ChevronLeft size={14}/></button></div></article>; })}</div> : <Empty title="لا توجد واجبات بعد" text="أضف واجباً أو حفظاً لتبدأ متابعة إنجاز الطلاب." icon={BookOpen}/>}</section></>;
}
function AnalyticsView() {
  const { data, month, setMonth, exportCSV, printReport } = useApp(); const [year,setYear] = useState(new Date().getFullYear()); const [group,setGroup] = useState(0); const income = data.payments.filter(p => p.paymentDate.startsWith(month) && (!group || p.groupId === group)).reduce((n,p) => n+p.amount,0); const expenses = data.expenses.filter(e => e.expenseDate.startsWith(month)).reduce((n,e) => n+e.amount,0);
  return <><PageHeading eyebrow="الأرقام والتقارير" title="التقارير والتحليلات" description="نظرة أوضح على أداء دروسك وحساباتك."><button className="button button-light" onClick={printReport}><Printer size={16}/> طباعة PDF</button><button className="button button-primary" onClick={exportCSV}><Download size={16}/> تصدير Excel</button></PageHeading><div className="report-filters"><span><BarChart3 size={17}/> خيارات العرض</span><div><select value={group} onChange={e => setGroup(Number(e.target.value))} aria-label="تصفية المجموعة"><option value={0}>كل المجموعات</option>{data.groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select><select value={year} onChange={e => setYear(Number(e.target.value))} aria-label="تصفية السنة">{Array.from({length:6},(_,i) => new Date().getFullYear()-i).map(y => <option key={y} value={y}>{y}</option>)}</select><MonthInput value={month} onChange={setMonth}/></div></div><div className="page-summary-row"><div><span className="summary-icon green"><TrendingUp size={19}/></span><span><small>إيرادات {monthLabel(month)}</small><strong>{money(income)}</strong></span></div><div><span className="summary-icon orange"><TrendingDown size={19}/></span><span><small>مصروفات الشهر العامة</small><strong>{money(expenses)}</strong></span></div><div><span className="summary-icon blue"><Wallet size={19}/></span><span><small>صافي الربح</small><strong>{money(income-expenses)}</strong></span></div></div><div className="reports-grid"><section className="card report-wide"><SectionHeading title="الإيرادات مقابل المصروفات" subtitle={`التحصيل الفعلي والمصروفات العامة خلال ${year}`}/><div className="chart-legend"><span><i className="blue-dot"/> الإيرادات</span><span><i className="green-dot"/> المصروفات</span></div><FinanceChart data={data} groupId={group} year={year}/></section><section className="card"><SectionHeading title="صافي الربح الشهري" subtitle="الإيرادات مطروحاً منها المصروفات"/><ProfitChart data={data} groupId={group} year={year}/></section><section className="card"><SectionHeading title="الطلاب حسب المجموعة" subtitle="توزيع الطلاب على المجموعات"/><GroupChart data={data} groupId={group}/></section><section className="card"><SectionHeading title="إحصاءات الحضور" subtitle={monthLabel(month)}/><AttendanceChart data={data} month={month} groupId={group}/></section><section className="card"><SectionHeading title="المصروفات حسب التصنيف" subtitle={monthLabel(month)}/><ExpenseChart data={data} month={month}/></section><section className="card"><SectionHeading title="المدفوع وغير المدفوع" subtitle={`إجمالي الطلاب · ${monthLabel(month)}`}/><PaymentDonut data={group ? { ...data, students:data.students.filter(s => data.memberships.some(m => m.studentId === s.id && m.groupId === group)), memberships:data.memberships.filter(m => m.groupId === group) } : data} month={month}/></section></div>{group > 0 && <p className="report-note">ملاحظة: المصروفات عامة وليست مرتبطة بمجموعة محددة، لذا يخصم إجماليها عند عرض صافي ربح المجموعة.</p>}</>;
}
function SettingsView() {
  const { authenticated, busy, open, logout, downloadBackup, restoreBackup, exportCSV, printReport } = useApp();
  const backupInput = useRef<HTMLInputElement>(null);
  return <><PageHeading eyebrow="إدارة الحساب" title="الإعدادات والنسخ الاحتياطي" description="تحكم بحسابك واحتفظ بنسخة من بياناتك بأمان."/><div className="settings-grid"><section className="card settings-card"><span className="summary-icon blue"><ShieldCheck size={22}/></span><h2>أمان الحساب</h2><p>جلسة آمنة لحساب المعلم. يمكنك تحديث كلمة المرور في أي وقت.</p><div className="settings-detail"><span>اسم المعلم</span><strong>مستر ميخائيل توما</strong></div><div className="settings-detail"><span>اسم المستخدم</span><strong dir="ltr">mikhail</strong></div><button className="button button-light" onClick={() => open(authenticated ? { type:"password" } : { type:"login" }, authenticated)}><LockKeyhole size={16}/>{authenticated ? "تغيير كلمة المرور" : "تسجيل الدخول"}</button>{authenticated && <button className="button button-light" onClick={logout}><LogOut size={16}/> تسجيل الخروج</button>}</section><section className="card settings-card"><span className="summary-icon purple"><FileDown size={22}/></span><h2>النسخ الاحتياطي والتصدير</h2><p>نزّل نسخة من البيانات أو صدّر ملخص الطلاب والتقارير للرجوع إليها.</p><div className="export-options"><button onClick={downloadBackup}><div><strong>نسخة احتياطية كاملة</strong><span>جميع البيانات بصيغة JSON</span></div><Download size={18}/></button><input ref={backupInput} type="file" accept="application/json,.json" hidden onChange={e => { const file = e.target.files?.[0]; e.target.value = ""; if (file) void restoreBackup(file); }}/><button disabled={busy} onClick={() => authenticated ? backupInput.current?.click() : open({ type:"login" })}><div><strong>استعادة نسخة احتياطية</strong><span>استبدال البيانات الحالية من ملف JSON</span></div><FileDown size={18}/></button><button onClick={exportCSV}><div><strong>تصدير قائمة الطلاب</strong><span>ملف CSV متوافق مع Excel</span></div><Download size={18}/></button><button onClick={printReport}><div><strong>تقرير قابل للطباعة</strong><span>احفظه بصيغة PDF من نافذة الطباعة</span></div><Printer size={18}/></button></div></section></div></>;
}
